mapper.select:
select

from enterprise_report_info
order by ${query.orderBy}
limit #{query.simplePage.start},#{query.simplePage.end}

SELECT eri.enterprise_id,
       eri.period_id,
       eri.report_id,
       eri.old_report_id,
       eri.reason_return,
       eri.status,
       eri.period_start_time,
       eri.period_end_time,
       eri.created_at,
       eri.updated_at,
       eri.enterprise_nature,
       eri.enterprise_industry,
       eri.enterprise_region,
       ei.name AS enterprise_name,
       ri.construction_count,
       ri.investigation_count,
       pi.investigate_time
FROM enterprise_report_info eri
left join enterprise_info ei on eri.enterprise_id = ei.enterprise_id
LEFT JOIN report_info ri ON eri.report_id = ri.report_id
LEFT JOIN period_info pi ON eri.period_id = pi.period_id


		and eri.enterprise_id = #{query.enterpriseId}


		and eri.period_id = #{query.periodId}


		and eri.report_id = #{query.reportId}


		and eri.old_report_id = #{query.oldReportId}


		and eri.reason_return = #{query.reasonReturn}


		and eri.status = #{query.status}


		and eri.period_start_time = #{query.periodStartTime}


		and eri.period_end_time = #{query.periodEndTime}


		and eri.created_at = #{query.createdAt}


		and eri.updated_at = #{query.updatedAt}


		and eri.enterprise_nature = #{query.enterpriseNature}


		and eri.enterprise_industry = #{query.enterpriseIndustry}


		and eri.enterprise_region = #{query.enterpriseRegion}



order by ${query.orderBy}
limit #{query.simplePage.start},#{query.simplePage.end}

SELECT COALESCE(ei.region, eri.enterprise_region) as region_code, COUNT(DISTINCT eri.enterprise_id) as enterprise_count, SUM(IFNULL(ri.construction_count, 0)) as construction_total, SUM(IFNULL(ri.investigation_count, 0)) as investigation_total
FROM enterprise_report_info eri LEFT JOIN report_info ri ON eri.report_id = ri.report_id LEFT JOIN enterprise_info ei ON eri.enterprise_id = ei.enterprise_id
WHERE 1=1
AND eri.period_id IN
#{periodId}
AND eri.status IN
#{status}
AND COALESCE(ei.region, eri.enterprise_region) IN
#{region}
GROUP BY COALESCE(ei.region, eri.enterprise_region) ORDER BY enterprise_count DESC
